{"operation":"run_python","code":"def check_min_cubes():
    # Grid is x in {0,1}, y in {0,1}, z in {0,1}
    # Front view requires: (0,0), (0,1), (1,0) in (x,y)
    # Side view requires: (0,0), (0,1), (1,0) in (z,y)

    front_req = {(0,0), (0,1), (1,0)}
    side_req = {(0,0), (0,1), (1,0)}

    all_cubes = [(x,y,z) for x in range(2) for y in range(2) for z in range(2)]

    from itertools import combinations

    for k in range(1, 9):
        for combo in combinations(all_cubes, k):
            # Check projections
            front_proj = set((c[0], c[1]) for c in combo)
            side_proj = set((c[2], c[1]) for c in combo)

            if front_req.issubset(front_proj) and side_req.issubset(side_proj):
                # Check connectivity
                # BFS from first cube
                visited = {combo[0]}
                queue = [combo[0]]
                while queue:
                    curr = queue.pop(0)
                    for nb in combo:
                        if nb not in visited:
                            dist = abs(curr[0]-nb[0]) + abs(curr[1]-nb[1]) + abs(curr[2]-nb[2])
                            if dist == 1: # share a face
                                visited.add(nb)
                                queue.append(nb)
                if len(visited) == k:
                    return k, combo
    return None

print(check_min_cubes())"}

