{"operation":"run_python","code":"def solve():
    n = 200
    powers = [4, 8, 16, 32, 64, 128, 256]

    # Build adjacency list
    adj = {i: [] for i in range(1, n + 1)}
    for x in range(1, n + 1):
        for p in powers:
            y = p - x
            if 1 <= y <= n and y != x:
                adj[x].append(y)

    # Find connected components and check bipartiteness
    visited = {i: False for i in range(1, n + 1)}
    num_components = 0
    all_bipartite = True

    for start_node in range(1, n + 1):
        if not visited[start_node]:
            num_components += 1
            # BFS to find component and check bipartiteness
            queue = [start_node]
            visited[start_node] = True
            color = {start_node: 0}
            is_bipartite = True

            idx = 0
            while idx < len(queue):
                u = queue[idx]
                idx += 1
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        color[v] = 1 - color[u]
                        queue.append(v)
                    else:
                        if color[v] == color[u]:
                            is_bipartite = False

            if not is_bipartite:
                all_bipartite = False

    if all_bipartite:
        return 2 ** num_components
    else:
        return 0

print(solve())"}

